"""Regenerate ../tables_gen.go from the pypdf package (BSD-3-Clause).

The tables are the data pypdf's text extraction depends on: the single-byte
encodings (pypdf/_codecs), the Adobe glyph list as extended by pypdf
(pypdf/_codecs/adobe_glyphs.py) and the standard-14 font metrics
(pypdf/_codecs/core_font_metrics.py, derived from Adobe's Core14 AFM files).

Usage (pypdf must be importable), from internal/pdftext:
    python -I testdata/gen_tables.py > tables_gen.go && gofmt -w tables_gen.go
"""

import site
import sys

try:
    import pypdf  # noqa: F401
except ImportError:
    sys.path.append(site.getusersitepackages())
    import pypdf  # noqa: F401

from pypdf._codecs import adobe_glyphs, charset_encoding
from pypdf._codecs.core_font_metrics import CORE_FONT_METRICS


def hexs(s: str) -> str:
    return ".".join("%X" % ord(c) for c in s)


out = []
w = out.append
w("// Code generated by testdata/gen_tables.py from pypdf %s; DO NOT EDIT." % pypdf.__version__)
w("//")
w("// The data comes from pypdf (Copyright (c) 2006-2008 Mathieu Fenniak and")
w("// contributors, BSD-3-Clause), which in turn contains the Adobe Glyph List")
w("// (Copyright 2002-2019 Adobe, BSD-3-Clause) and metrics from Adobe's Core 14")
w("// AFM files (Copyright 1985-1997 Adobe Systems Incorporated; may be used,")
w("// copied and distributed for any purpose provided the copyright notices are")
w("// retained). Each value is a sequence of Python code points written as hex")
w("// numbers joined by '.'; surrogate halves are kept as pypdf has them.")
w("")
w("package pdftext")
w("")
w("// charsetTables: name, then 256 code-point sequences separated by spaces.")
w("const charsetTablesData = `")
for name, lst in charset_encoding.items():
    assert len(lst) == 256
    w(name + " " + " ".join(hexs(c) for c in lst))
w("`")
w("")
w("// adobeGlyphsData: one 'name value' pair per line.")
w("const adobeGlyphsData = `")
for k, v in adobe_glyphs.items():
    assert " " not in k and "\n" not in k and "`" not in k, k
    w(k + " " + hexs(v))
w("`")
w("")
w("// coreFontsData: 'font flags', then 'char width' pairs; 'default' is the key")
w("// for the default width. A blank line ends each font.")
w("const coreFontsData = `")
for name, m in CORE_FONT_METRICS.items():
    w("%s %d" % (name, m.font_descriptor.flags))
    for ch, width in m.character_widths.items():
        assert isinstance(width, int), (name, ch, width)
        w("%s %d" % ("default" if ch == "default" else hexs(ch), width))
    w("")
w("`")
sys.stdout.buffer.write(("\n".join(out) + "\n").encode("utf-8"))  # LF line endings on Windows too
